"""One versioned profile snapshot per interpreter, detached mutable API copies."""
import copy,os,stat,threading,time


class PortalReadError(RuntimeError):
    def __init__(self,message='Portale vorübergehend nicht verfügbar.',reason='UNKNOWN'):
        self.reason=reason;super().__init__(message)



class Snapshot:
    def __init__(self):
        self.lock=threading.RLock();self.key=None;self.value=None;self.retry=0;self.failures=0

    def invalidate(self):
        with self.lock:self.key=None;self.value=None;self.retry=0;self.failures=0

    @staticmethod
    def version(path):
        try:s=os.stat(path)
        except FileNotFoundError:
            if os.path.lexists(path):raise ValueError('Invalid profile file')
            return (path,None)
        return (path,s.st_dev,s.st_ino,s.st_size,s.st_mtime_ns,s.st_ctime_ns)

    def read(self,path,types,select=lambda rows:rows):
        from boot_diagnostics import phase
        from profile_transaction import reading
        from service_runtime import portal_call,portal_read,portal_failure,note_pressure
        portal_call()
        # A detached, already validated generation is safe while an unrelated
        # image/cache writer owns the profile lock. Recheck the actual file
        # identity after copying; a replacement/deletion never inherits it.
        with self.lock:
            key=self.version(path)
            if self.value is not None and key==self.key:
                try:result=copy.deepcopy(select(self.value))
                except MemoryError:
                    self.value=None;self.failures=min(5,self.failures+1);self.retry=time.monotonic()+min(30,2**self.failures)
                    portal_failure('OOM');note_pressure()
                    raise PortalReadError(reason='MEMORY') from None
                if self.version(path)==key:return result
        with self.lock,reading():
            key=self.version(path)
            if key!=self.key:self.value=None;self.retry=0;self.failures=0;self.key=key
            if time.monotonic()<self.retry:raise PortalReadError('Portale: Speicherpause aktiv. Bitte kurz warten und erneut öffnen.',reason='MEMORY_PAUSE')
            try:
                if self.value is None:
                    with phase('PORTALS_LOAD'):
                        for attempt in range(2):
                            key=self.version(path)
                            if key[1] is None:self.value=[];self.key=key;break
                            fd=os.open(path,os.O_RDONLY|getattr(os,'O_NONBLOCK',0))
                            with os.fdopen(fd,'rb') as stream:
                                actual=os.fstat(stream.fileno())
                                if not stat.S_ISREG(actual.st_mode):raise PortalReadError(reason='INVALID_PROFILE')
                                if actual.st_size>4*1024*1024:raise PortalReadError('Portalliste überschreitet das sichere Leselimit.',reason='PROFILE_BUDGET')
                                raw=stream.read(4*1024*1024+1)
                            if len(raw)>4*1024*1024:raise PortalReadError('Portalliste überschreitet das sichere Leselimit.',reason='PROFILE_BUDGET')
                            import json
                            value=json.loads(raw)
                            if not isinstance(value,list) or any(not isinstance(p,dict) or not isinstance(p.get('id'),str) or not p['id'] or p.get('type') not in types for p in value):raise PortalReadError(reason='INVALID_PROFILE')
                            if self.version(path)!=key:continue
                            self.key=key;self.value=value;portal_read(len(raw));break
                        else:raise PortalReadError('Portale wurden gleichzeitig geändert. Bitte erneut öffnen.',reason='PROFILE_RACE')
                # Never expose cached credentials/groups to mutable callers.
                result=copy.deepcopy(select(self.value));self.failures=0;self.retry=0
                return result
            except MemoryError:
                self.value=None;self.failures=min(5,self.failures+1);self.retry=time.monotonic()+min(30,2**self.failures)
                portal_failure('OOM');note_pressure()
                raise PortalReadError('Portale konnten wegen Speicherknappheit nicht gelesen werden. Daten unverändert; kurz warten und erneut öffnen.',reason='MEMORY') from None
            except Exception:
                self.value=None;portal_failure('READ_ERROR')
                raise

"""Finite, reentrant cross-interpreter lock for local profile configuration.

Kodi Android/Linux uses flock. The lock file contains no user data; reads and
normal startup do not acquire this write lock.
"""
from contextlib import contextmanager
from functools import wraps
import os
import threading
import time

_guard=threading.RLock()
_local=threading.local()


@contextmanager
def writing(timeout=1):
    from utils import addon_data_dir
    if not _guard.acquire(timeout=timeout): raise TimeoutError('profile write busy')
    try:
        if getattr(_local,'depth',0):
            _local.depth+=1
            try: yield
            finally: _local.depth-=1
            return
        import fcntl
        descriptor=os.open(os.path.join(addon_data_dir(),'.xcmate-config.lock'),os.O_CREAT|os.O_RDWR,0o600)
        deadline=time.monotonic()+timeout
        try:
            while True:
                try: fcntl.flock(descriptor,fcntl.LOCK_EX|fcntl.LOCK_NB);break
                except BlockingIOError:
                    if time.monotonic()>=deadline: raise TimeoutError('profile write busy')
                    time.sleep(.02)
            _local.depth=1
            try: yield
            finally: _local.depth=0;fcntl.flock(descriptor,fcntl.LOCK_UN)
        finally: os.close(descriptor)
    finally: _guard.release()


def serialized(function):
    @wraps(function)
    def wrapped(*args,**kwargs):
        with writing(): return function(*args,**kwargs)
    return wrapped


@contextmanager
def reading(timeout=.15):
    """Do not observe a half-committed multi-file configuration transaction.

    Legacy read-only profiles need no new file. A thread already holding our
    reentrant writer lock may verify its own write without a flock deadlock.
    """
    if getattr(_local,'depth',0):yield;return
    from utils import addon_data_dir
    path=os.path.join(addon_data_dir(),'.xcmate-config.lock')
    try:fd=os.open(path,os.O_RDONLY)
    except FileNotFoundError:yield;return
    import fcntl
    try:
        deadline=time.monotonic()+timeout
        while True:
            try:fcntl.flock(fd,fcntl.LOCK_SH|fcntl.LOCK_NB);break
            except BlockingIOError:
                if time.monotonic()>=deadline:raise TimeoutError('profile read busy')
                time.sleep(.005)
        yield
    finally:os.close(fd)

